function StringToCString(s) {
	var strLen = s.length;
	var arr = new Uint8Array(strLen + 1);
	for (var i = 0; i < strLen; i++)
		arr[i] = s.charCodeAt(i);
	arr[strLen] = 0;
	return arr;
}

function StringToArray(s) {
	var utf8 = unescape(encodeURIComponent(s));

	var arr = [];
	for (var i = 0; i < utf8.length; i++) {
		arr.push(utf8.charCodeAt(i));
	}
	return arr;
}

function ArrayToString(arr) {
	var ret = [];
	
	var length = arr.length;
	if (length > 0 && 
		arr[length - 1] == 0) {
		length -= 1;
	}
	
	for (var i = 0; i < length; i++) {
		var chr = arr[i];
		if (chr > 0xFF) {
			chr &= 0xFF;
		}

		ret.push(String.fromCharCode(chr));
	}

	return  decodeURIComponent(escape(ret.join('')));
}

function UTF8ToCP1251Array(s) {
	var L = [];
	for (var i = 0; i < s.length; i++) {
		var ord = s.charCodeAt(i);
		if (!(ord in CP1251Table))
			throw "Character " + s.charAt(i) + " isn't supported by win1251!";
		L.push(CP1251Table[ord]);
	}

	L.push(0);

	return L;
}

function CP1251PointerToUTF8(ptr) {
	var t;
	var i = 0;
	var ret = '';

	var code2char = function(code) {
		if(code >= 0xC0 && code <= 0xFF)
			return String.fromCharCode(code - 0xC0 + 0x0410);
		if(code >= 0x80 && code <= 0xBF) 
			return UTF8Table.charAt(code - 0x80);
		return String.fromCharCode(code);
	};

	while (1) {
		t = HEAPU8[(((ptr)+(i))|0)];
		if (t == 0) 
			break;
		ret += code2char(t);
		i++;
	}

	return ret;
}


function StringToUTF16LEArray(str, zero) {
	var L = [];
	var c;

	for (var i = 0; i < str.length; i++) {
		c = str.charCodeAt(i);
		L.push(c & 0xFF);
		L.push((c & 0xFF00) >> 8);
	}
	
	if (zero) {
		L.push(0);
		L.push(0);
	}
	
	return L;
}

function UTF16LEArrayToString(arr) {
	var t1, t2;
	var i = 0;
	var ret = '';
	var length;

	if ((arr.length%2) != 0)
		return null;

	length = arr.length;
	if (length > 0 && 
		arr[length - 2] == 0 && 
		arr[length - 1] == 0) {
		length -= 2;
	}
		
	while (i < length) {
		ret += String.fromCharCode(arr[i] | (arr[i+1] << 8)); 
		i += 2;
	}

	return ret;
}

