		var keyIDsCount = dwordKeyIDsCountPtr.toNumber();
		var keyIDs = keyIDsPtr.toStringArray();
		if (keyIDsCount != keyIDs.length)
			this.RaiseError(EU_ERROR_BAD_PARAMETER);

		return EndUserPrivateKeyInfo(
			keyType, keyUsage, keyIDs);
